import React, { useState } from 'react';

const Dashboard = ({ onNavigate }) => { 
    const [pnrInput, setPnrInput] = useState('');
    const NGROK_URL = "https://your-ngrok-url.ngrok-free.app"; 
    const MY_PHONE_NUMBER = "+91XXXXXXXXXX"; // Put your number here

    const triggerVoiceCall = async () => {
        try {
            const response = await fetch(`${NGROK_URL}/make-call`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ to: MY_PHONE_NUMBER }) 
            });
            const data = await response.json();
            if (response.ok) {
                alert("Call Initiated!");
            } else {
                alert("Twilio Error: " + data.message);
            }
        } catch (err) {
            alert("Connection error. Check server and ngrok.");
        }
    };

    return (
        <div style={{ background: '#070b14', height: '100vh', display: 'flex', color: '#e2e8f0', fontFamily: 'serif', overflow: 'hidden' }}>
            <div style={{ width: '280px', borderRight: '1px solid #1e293b', display: 'flex', flexDirection: 'column', padding: '20px' }}>
                <h3 style={{ color: '#3b82f6', fontSize: '11px', marginBottom: '20px' }}>AIRPORT AMENITIES</h3>
                {["Reliance Digital", "Plaza Lounge", "Global Food Court", "Medical Center", "ATM / Currency"].map(item => (
                    <div key={item} style={{ background: '#111827', padding: '10px', borderRadius: '5px', fontSize: '11px', border: '1px solid #1e293b', marginBottom: '8px' }}>{item}</div>
                ))}
                <div style={{ marginTop: 'auto', display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    <button onClick={triggerVoiceCall} style={{ background: '#2563eb', color: 'white', padding: '12px', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}>📞 START VOICE CALL</button>
                    <button onClick={() => onNavigate('voiceweb')} style={{ background: '#1e3a8a', color: 'white', padding: '12px', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}>🌐 START VOICE WEB</button>
                </div>
            </div>

            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '40px' }}>
                <h1 style={{ letterSpacing: '10px', fontSize: '42px', color: '#3b82f6' }}>SKY-SYNC AI</h1>
                <p style={{ opacity: 0.5, marginBottom: '40px' }}>INTELLIGENT FLIGHT OPERATIONAL SYSTEM</p>
                <div style={{ width: '80%', display: 'flex', gap: '10px', marginBottom: '40px' }}>
                    <input type="text" placeholder="ENTER PNR NUMBER..." value={pnrInput} onChange={(e) => setPnrInput(e.target.value.toUpperCase())} style={{ flex: 1, background: '#111827', border: '1px solid #3b82f6', padding: '12px', color: 'white', borderRadius: '8px' }} />
                    <button onClick={() => onNavigate('pnr-tracking', pnrInput)} style={{ background: '#3b82f6', color: 'white', padding: '0 25px', borderRadius: '8px', border: 'none', cursor: 'pointer' }}>TRACK STATUS</button>
                </div>
                <div style={{ width: '95%', flex: 1, background: '#111827', borderRadius: '12px', border: '1px solid #1e293b', overflow: 'hidden' }}>
                    <div style={{ padding: '10px', color: '#60a5fa', fontSize: '11px' }}>LIVE FLIGHT RADAR</div>
                    <div style={{ overflowY: 'auto', maxHeight: '300px', padding: '10px' }}>
                        {[...Array(15)].map((_, i) => (
                            <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '10px', fontSize: '12px', borderBottom: '1px solid #0f172a' }}>
                                <span>AI-{100 + i} BOM ➔ LHR</span>
                                <span style={{ color: i % 4 === 0 ? '#ef4444' : '#22c55e' }}>{i % 4 === 0 ? 'DELAY' : 'ON TIME'}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            <div style={{ width: '300px', borderLeft: '1px solid #1e293b', padding: '20px' }}>
                <div style={{ background: '#111827', padding: '15px', borderRadius: '10px', border: '1px solid #1e293b', marginBottom: '20px' }}>
                    <p style={{ color: '#60a5fa', fontSize: '10px' }}>TEMPERATURE</p>
                    <div style={{ fontSize: '24px' }}>28°C <span style={{ fontSize: '12px', opacity: 0.5 }}>Vijayawada</span></div>
                </div>
                <div style={{ background: '#111827', padding: '15px', borderRadius: '10px', border: '1px solid #1e293b' }}>
                    <p style={{ color: '#60a5fa', fontSize: '10px' }}>WORLD CLOCKS</p>
                    <div style={{ fontSize: '12px' }}>New Delhi: {new Date().toLocaleTimeString()}</div>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
